#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void tensor_matmul_kernel(const float* A, const float* B, float* C, int b, int i, int j, int l, int k) {
    int idx_b = blockIdx.z;
    int idx_i = blockIdx.y;
    int idx_j = blockIdx.x;
    int idx_k = threadIdx.x;

    float value = 0.0f;
    for (int idx_l = 0; idx_l < l; ++idx_l) {
        value += A[idx_b * i * j * l + idx_i * j * l + idx_j * l + idx_l] * B[idx_l * k + idx_k];
    }
    C[idx_b * i * j * k + idx_i * j * k + idx_j * k + idx_k] = value;
}

torch::Tensor tensor_matmul_rocm(torch::Tensor A, torch::Tensor B) {
    auto b = A.size(0);
    auto i = A.size(1);
    auto j = A.size(2);
    auto l = A.size(3);
    auto k = B.size(1);

    auto C = torch::zeros({b, i, j, k}, A.options());

    dim3 blocks(j, i, b);
    int threads = k;

    tensor_matmul_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), b, i, j, l, k);

    return C;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float value = 0.0f;
        for (int k = 0; k < K; ++k) {
            value += A[k * M + row] * B[k * N + col];
        }
        C[row * N + col] = value;
    }
}

torch::Tensor matmul_rocm(torch::Tensor A, torch::Tensor B) {
    int M = A.size(1);
    int K = A.size(0);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 threads(32, 32);
    dim3 blocks((N + threads.x - 1) / threads.x, (M + threads.y - 1) / threads.y);

    hipLaunchKernelGGL(matmul_kernel, blocks, threads, 0, 0,
                       A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, K, N);

    return C;
}

