#include <ATen/hip/HIPContext.h>

__global__ void mean_reduction_kernel(const float* input, float* output, int outer_size, int inner_size, int dim_size) {
    int outer_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int inner_idx = blockIdx.y * blockDim.y + threadIdx.y;

    if (outer_idx < outer_size && inner_idx < inner_size) {
        float sum = 0.0f;
        for (int i = 0; i < dim_size; ++i) {
            int input_idx = outer_idx * dim_size * inner_size + i * inner_size + inner_idx;
            sum += input[input_idx];
        }
        int output_idx = outer_idx * inner_size + inner_idx;
        output[output_idx] = sum / dim_size;
    }
}

torch::Tensor mean_reduction_rocm(torch::Tensor input, int dim) {
    auto input_sizes = input.sizes();
    int outer_size = 1;
    for (int i = 0; i < dim; ++i) {
        outer_size *= input_sizes[i];
    }
    int dim_size = input_sizes[dim];
    int inner_size = 1;
    for (int i = dim + 1; i < input.dim(); ++i) {
        inner_size *= input_sizes[i];
    }

    auto output_sizes = input_sizes.vec();
    output_sizes.erase(output_sizes.begin() + dim);
    auto output = torch::zeros(output_sizes, input.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((outer_size + block_size.x - 1) / block_size.x, (inner_size + block_size.y - 1) / block_size.y);

    mean_reduction_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), outer_size, inner_size, dim_size);

    return output;
}

