__global__ void l1_norm_kernel(const float* x, float* out, int batch_size, int dim) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < batch_size) {
        float sum = 0.0f;
        for (int j = 0; j < dim; j++) {
            sum += fabsf(x[i * dim + j]);
        }
        for (int j = 0; j < dim; j++) {
            out[i * dim + j] = x[i * dim + j] / sum;
        }
    }
}

torch::Tensor l1_norm_rocm(torch::Tensor x) {
    int batch_size = x.size(0);
    int dim = x.size(1);
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    l1_norm_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), batch_size, dim);

    return out;
}

