#include <hip/hip_runtime.h>

__global__ void maxpool3d_kernel(const float* input, float* output, int batch_size, int channels, int input_dim1, int input_dim2, int input_dim3, int output_dim1, int output_dim2, int output_dim3, int kernel_size, int stride, int padding, int dilation) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * channels * output_dim1 * output_dim2 * output_dim3;
    if (idx < total) {
        int b = idx / (channels * output_dim1 * output_dim2 * output_dim3);
        int c = (idx / (output_dim1 * output_dim2 * output_dim3)) % channels;
        int od1 = (idx / (output_dim2 * output_dim3)) % output_dim1;
        int od2 = (idx / output_dim3) % output_dim2;
        int od3 = idx % output_dim3;

        float max_val = -FLT_MAX;
        for (int kd1 = 0; kd1 < kernel_size; ++kd1) {
            for (int kd2 = 0; kd2 < kernel_size; ++kd2) {
                for (int kd3 = 0; kd3 < kernel_size; ++kd3) {
                    int id1 = od1 * stride + kd1 * dilation - padding;
                    int id2 = od2 * stride + kd2 * dilation - padding;
                    int id3 = od3 * stride + kd3 * dilation - padding;
                    if (id1 >= 0 && id1 < input_dim1 && id2 >= 0 && id2 < input_dim2 && id3 >= 0 && id3 < input_dim3) {
                        int i_idx = b * channels * input_dim1 * input_dim2 * input_dim3 +
                                    c * input_dim1 * input_dim2 * input_dim3 +
                                    id1 * input_dim2 * input_dim3 +
                                    id2 * input_dim3 +
                                    id3;
                        max_val = fmaxf(max_val, input[i_idx]);
                    }
                }
            }
        }
        output[idx] = max_val;
    }
}

torch::Tensor maxpool3d_rocm(torch::Tensor input, int kernel_size, int stride, int padding, int dilation, bool return_indices, bool ceil_mode) {
    int batch_size = input.size(0);
    int channels = input.size(1);
    int input_dim1 = input.size(2);
    int input_dim2 = input.size(3);
    int input_dim3 = input.size(4);

    int output_dim1 = (input_dim1 + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int output_dim2 = (input_dim2 + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int output_dim3 = (input_dim3 + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    if (ceil_mode) {
        output_dim1 = (input_dim1 + 2 * padding - dilation * (kernel_size - 1) - 1 + stride - 1) / stride + 1;
        output_dim2 = (input_dim2 + 2 * padding - dilation * (kernel_size - 1) - 1 + stride - 1) / stride + 1;
        output_dim3 = (input_dim3 + 2 * padding - dilation * (kernel_size - 1) - 1 + stride - 1) / stride + 1;
    }

    auto output = torch::zeros({batch_size, channels, output_dim1, output_dim2, output_dim3}, input.options());

    int total_elements = batch_size * channels * output_dim1 * output_dim2 * output_dim3;
    int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(maxpool3d_kernel, num_blocks, block_size, 0, 0, input.data_ptr<float>(), output.data_ptr<float>(), batch_size, channels, input_dim1, input_dim2, input_dim3, output_dim1, output_dim2, output_dim3, kernel_size, stride, padding, dilation);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

#define CHECK_HIP(x) TORCH_CHECK(x.is_cuda(), #x " must be a HIP tensor")
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")

__global__ void conv_transpose2d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int B, int Cin, int H, int W,
    int Cout, int KH, int KW,
    int Sx, int Sy,
    int Px, int Py,
    int OPx, int OPy,
    int Dx, int Dy,
    int G,
    int outH, int outW) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int idy = blockIdx.y * blockDim.y + threadIdx.y;
    int batch = blockIdx.z;

    if (batch >= B || idy >= outH || idx >= outW) return;

    for (int group = 0; group < G; ++group) {
        int Cin_group = Cin / G;
        int Cout_group = Cout / G;

        for (int c_out = group * Cout_group; c_out < (group + 1) * Cout_group; ++c_out) {
            float total = bias ? bias[c_out] : 0.0f;

            for (int ky = 0; ky < KH; ++ky) {
                for (int kx = 0; kx < KW; ++kx) {
                    int h_in = (idy - ky * Dy + Py);
                    if (h_in % Sy != 0) continue;
                    h_in /= Sy;

                    int w_in = (idx - kx * Dx + Px);
                    if (w_in % Sx != 0) continue;
                    w_in /= Sx;

                    if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                        for (int c_in = group * Cin_group; c_in < (group + 1) * Cin_group; ++c_in) {
                            float val = input[batch * Cin * H * W + c_in * H * W + h_in * W + w_in];
                            float w = weight[c_in * Cout_group * KH * KW + (c_out % Cout_group) * KH * KW + ky * KW + kx];
                            total += val * w;
                        }
                    }
                }
            }
            output[batch * Cout * outH * outW + c_out * outH * outW + idy * outW + idx] = total;
        }
    }
}

torch::Tensor conv_transpose_rocm(
    torch::Tensor input, 
    torch::Tensor weight, 
    c10::optional<torch::Tensor> bias,
    int Sx, int Sy,
    int Px, int Py,
    int OPx, int OPy,
    int Dx, int Dy,
    int G) {

    CHECK_HIP(input);
    CHECK_HIP(weight);
    CHECK_CONTIGUOUS(input);
    CHECK_CONTIGUOUS(weight);
    if (bias.has_value()) {
        CHECK_HIP(bias.value());
        CHECK_CONTIGUOUS(bias.value());
    }

    int B = input.size(0);
    int Cin = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int KH = weight.size(2);
    int KW = weight.size(3);
    int Cout = weight.size(1) * G;

    int outH = (H - 1)*Sy + KH*Dy - 2*Py + OPy;
    int outW = (W - 1)*Sx + KW*Dx - 2*Px + OPx;

    auto output = torch::zeros({B, Cout, outH, outW}, input.options());

    dim3 threads(32, 8);
    dim3 blocks((outW + threads.x - 1)/threads.x, (outH + threads.y - 1)/threads.y, B);

    float* bias_ptr = bias.has_value() ? bias->data_ptr<float>() : nullptr;

    hipLaunchKernelGGL(
        conv_transpose2d_kernel, 
        blocks, threads, 0, at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        B, Cin, H, W,
        Cout, KH, KW,
        Sx, Sy,
        Px, Py,
        OPx, OPy,
        Dx, Dy,
        G,
        outH, outW
    );
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void product_reduction_kernel(const float* x, float* out, int dim_size, int outer_size, int inner_size) {
    int outer_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int inner_idx = blockIdx.y * blockDim.y + threadIdx.y;

    if (outer_idx < outer_size && inner_idx < inner_size) {
        float prod = 1.0f;
        for (int i = 0; i < dim_size; ++i) {
            prod *= x[outer_idx * dim_size * inner_size + i * inner_size + inner_idx];
        }
        out[outer_idx * inner_size + inner_idx] = prod;
    }
}

torch::Tensor product_reduction_rocm(torch::Tensor x, int dim) {
    auto sizes = x.sizes();
    int dim_size = sizes[dim];
    int outer_size = 1;
    for (int i = 0; i < dim; ++i) {
        outer_size *= sizes[i];
    }
    int inner_size = 1;
    for (int i = dim + 1; i < x.dim(); ++i) {
        inner_size *= sizes[i];
    }

    auto out = torch::zeros({outer_size, inner_size}, x.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((outer_size + block_size.x - 1) / block_size.x, (inner_size + block_size.y - 1) / block_size.y);

    product_reduction_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), dim_size, outer_size, inner_size);

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void depthwise_conv_kernel(
    const float* input,
    const float* weight,
    float* output,
    int batch_size,
    int in_channels,
    int H_in,
    int W_in,
    int K,
    int H_out,
    int W_out,
    int stride_h,
    int padding_h,
    int dilation_h
) {
    const int global_idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total_output = batch_size * in_channels * H_out * W_out;
    if (global_idx >= total_output) return;

    int n = global_idx / (in_channels * H_out * W_out);
    int rem = global_idx % (in_channels * H_out * W_out);
    int c = rem / (H_out * W_out);
    rem = rem % (H_out * W_out);
    int h_out = rem / W_out;
    int w_out = rem % W_out;

    const float* weight_ptr = weight + c * K;
    float sum = 0.0f;

    for (int k = 0; k < K; ++k) {
        int h_in = h_out * stride_h - padding_h + k * dilation_h;
        if (h_in >= 0 && h_in < H_in) {
            int input_idx = n * in_channels * H_in * W_in + c * H_in * W_in + h_in * W_in + w_out;
            sum += input[input_idx] * weight_ptr[k];
        }
    }

    output[global_idx] = sum;
}

torch::Tensor depthwise_conv_rocm(
    torch::Tensor input,
    torch::Tensor weight,
    int H_kernel,
    int stride_h,
    int padding_h,
    int dilation_h
) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int H_out = (H_in + 2 * padding_h - dilation_h * (H_kernel - 1) - 1) / stride_h + 1;
    int W_out = W_in;

    auto output = torch::zeros({batch_size, in_channels, H_out, W_out}, input.options());
    int total_output = output.numel();

    const int block_size = 256;
    int num_blocks = (total_output + block_size - 1) / block_size;

    depthwise_conv_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        H_in,
        W_in,
        H_kernel,
        H_out,
        W_out,
        stride_h,
        padding_h,
        dilation_h
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void avg_pool1d_kernel(const float* input, float* output, int batch_size, int in_channels, int input_length, int output_length, int kernel_size, int stride, int padding) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int channel = blockIdx.y;
    int batch = blockIdx.z;
    if (idx < output_length && channel < in_channels && batch < batch_size) {
        float sum = 0.0f;
        int start = idx * stride - padding;
        int end = start + kernel_size;
        start = max(start, 0);
        end = min(end, input_length);
        int count = end - start;
        for (int i = start; i < end; ++i) {
            sum += input[batch * in_channels * input_length + channel * input_length + i];
        }
        output[batch * in_channels * output_length + channel * output_length + idx] = sum / (float)kernel_size;
    }
}

torch::Tensor avg_pool1d_rocm(torch::Tensor input, int kernel_size, int stride, int padding) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_length = input.size(2);
    int output_length = (input_length + 2 * padding - kernel_size) / stride + 1;
    auto output = torch::zeros({batch_size, in_channels, output_length}, input.options());

    dim3 block_size(256);
    dim3 grid_size((output_length + block_size.x - 1) / block_size.x, in_channels, batch_size);

    hipStream_t stream = at::hip::getCurrentHIPStreamMasqueradingAsCUDA();
    avg_pool1d_kernel<<<grid_size, block_size, 0, stream>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        input_length,
        output_length,
        kernel_size,
        stride,
        padding
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void matmul_kernel(const float* A, const float* B, float* out, int M, int K) {
    __shared__ float B_shr[16][16];

    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int j_block = blockIdx.y * blockDim.y;
    int j = j_block + threadIdx.y;

    if (j >= M) return;

    for (int k = 0; k < K; ++k) {
        B_shr[k][threadIdx.y] = B[k * M + j];
    }
    __syncthreads();

    if (i >= M) return;

    float sum = 0.0f;
    for (int k = 0; k < K; ++k) {
        sum += A[i * K + k] * B_shr[k][threadIdx.y];
    }
    out[i * M + j] = sum;
}

torch::Tensor matmul_rocm(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D");
    int M = A.size(0);
    int K = A.size(1);
    TORCH_CHECK(B.size(0) == K, "Invalid dimensions");

    auto out = torch::zeros({M, M}, A.options());

    dim3 block(32, 16);
    dim3 grid((M + block.x - 1) / block.x, (M + block.y - 1) / block.y);

    hipLaunchKernelGGL(matmul_kernel, grid, block, 0, at::hip::getCurrentHIPStream(), 
        A.data_ptr<float>(), B.data_ptr<float>(), out.data_ptr<float>(), M, K);

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void sum_reduction_kernel(const float* input, float* output, int batch_size, int dim1, int dim2, int reduce_dim) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (reduce_dim == 1) {
        if (idx < batch_size * dim2) {
            int b = idx / dim2;
            int d2 = idx % dim2;
            float sum = 0.0f;
            for (int d1 = 0; d1 < dim1; ++d1) {
                sum += input[b * dim1 * dim2 + d1 * dim2 + d2];
            }
            output[b * dim2 + d2] = sum;
        }
    } else if (reduce_dim == 2) {
        if (idx < batch_size * dim1) {
            int b = idx / dim1;
            int d1 = idx % dim1;
            float sum = 0.0f;
            for (int d2 = 0; d2 < dim2; ++d2) {
                sum += input[b * dim1 * dim2 + d1 * dim2 + d2];
            }
            output[b * dim1 + d1] = sum;
        }
    }
}

torch::Tensor sum_reduction_rocm(torch::Tensor input, int reduce_dim) {
    int batch_size = input.size(0);
    int dim1 = input.size(1);
    int dim2 = input.size(2);
    auto output = reduce_dim == 1 ? torch::zeros({batch_size, 1, dim2}, input.options()) : torch::zeros({batch_size, dim1, 1}, input.options());

    const int block_size = 256;
    const int num_blocks = (batch_size * dim2 + block_size - 1) / block_size;

    sum_reduction_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), batch_size, dim1, dim2, reduce_dim);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void elu_kernel(const float* x, float* out, float alpha, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = x[idx] > 0 ? x[idx] : alpha * (expf(x[idx]) - 1);
    }
}

torch::Tensor elu_rocm(torch::Tensor x, float alpha) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), alpha, size);

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void softmax_kernel(const float* input, float* output, int batch_size, int num_features) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size) {
        float max_val = input[idx * num_features];
        for (int i = 1; i < num_features; ++i) {
            if (input[idx * num_features + i] > max_val) {
                max_val = input[idx * num_features + i];
            }
        }

        float sum = 0.0f;
        for (int i = 0; i < num_features; ++i) {
            sum += expf(input[idx * num_features + i] - max_val);
        }

        for (int i = 0; i < num_features; ++i) {
            output[idx * num_features + i] = expf(input[idx * num_features + i] - max_val) / sum;
        }
    }
}

torch::Tensor softmax_rocm(torch::Tensor input) {
    int batch_size = input.size(0);
    int num_features = input.size(1);
    auto output = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    softmax_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), batch_size, num_features);

    return output;
}

