__global__ void diag_matmul_kernel(const float* A, const float* B, float* C, int N, int M) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;
    if (row < N && col < M) {
        C[row * M + col] = A[row] * B[row * M + col];
    }
}

torch::Tensor diag_matmul_rocm(torch::Tensor A, torch::Tensor B) {
    auto N = A.size(0);
    auto M = B.size(1);
    auto C = torch::zeros({N, M}, A.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((N + block_size.x - 1) / block_size.x, (M + block_size.y - 1) / block_size.y);

    diag_matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N, M);

    return C;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void min_reduction_kernel(const float* input, float* output, int dim_size, int stride, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        int inner_idx = idx % stride;
        int outer_idx = idx / stride;
        int start = outer_idx * stride * dim_size + inner_idx;
        float min_val = input[start];
        for (int i = 1; i < dim_size; ++i) {
            float val = input[start + i * stride];
            if (val < min_val) {
                min_val = val;
            }
        }
        output[idx] = min_val;
    }
}

torch::Tensor min_reduction_rocm(torch::Tensor input, int dim) {
    auto sizes = input.sizes().vec();
    auto dim_size = sizes[dim];
    sizes.erase(sizes.begin() + dim);
    auto output = torch::empty(sizes, input.options());

    int size = input.numel() / dim_size;
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    min_reduction_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), dim_size, input.stride(dim), size);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <limits>

__global__ void log_softmax_kernel(const float* x, float* out, int batch_size, int dim) {
    int batch_idx = blockIdx.x;
    int idx = threadIdx.x;

    if (batch_idx >= batch_size || idx >= dim) return;

    extern __shared__ float shared_max[];
    extern __shared__ float shared_exp_sum[];

    float max_val = -std::numeric_limits<float>::infinity();
    for (int i = 0; i < dim; i += blockDim.x) {
        int col = i + idx;
        if (col < dim) {
            float val = x[batch_idx * dim + col];
            if (val > max_val) {
                max_val = val;
            }
        }
    }

    shared_max[idx] = max_val;
    __syncthreads();

    for (int i = blockDim.x / 2; i > 0; i /= 2) {
        if (idx < i && idx + i < blockDim.x) {
            if (shared_max[idx + i] > shared_max[idx]) {
                shared_max[idx] = shared_max[idx + i];
            }
        }
        __syncthreads();
    }

    max_val = shared_max[0];

    float sum_exp = 0.0f;
    for (int i = 0; i < dim; i += blockDim.x) {
        int col = i + idx;
        if (col < dim) {
            sum_exp += __expf(x[batch_idx * dim + col] - max_val);
        }
    }

    shared_exp_sum[idx] = sum_exp;
    __syncthreads();

    for (int i = blockDim.x / 2; i > 0; i /= 2) {
        if (idx < i && idx + i < blockDim.x) {
            shared_exp_sum[idx] += shared_exp_sum[idx + i];
        }
        __syncthreads();
    }

    float log_sum_exp = __logf(shared_exp_sum[0]);

    for (int i = 0; i < dim; i += blockDim.x) {
        int col = i + idx;
        if (col < dim) {
            out[batch_idx * dim + col] = x[batch_idx * dim + col] - max_val - log_sum_exp;
        }
    }
}

torch::Tensor log_softmax_rocm(torch::Tensor x, int dim) {
    auto sizes = x.sizes();
    int batch_size = sizes[0];
    int dim_size = sizes[1];
    auto out = torch::zeros_like(x);

    int threads = min(dim_size, 256);
    int shared_memory_size = threads * 2 * sizeof(float);

    log_softmax_kernel<<<batch_size, threads, shared_memory_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), batch_size, dim_size);

    return out;
}

#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void argmax_kernel(const float* input, int64_t* output, int reduction_size, int stride_d, int step_d, int output_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= output_size) return;

    int base_idx = (idx / step_d) * reduction_size * stride_d + (idx % step_d);

    float max_val = -INFINITY;
    int max_idx = 0;

    for (int i=0; i<reduction_size; i++) {
        float val = input[base_idx + i*stride_d];
        if (val > max_val) {
            max_val = val;
            max_idx = i;
        }
        else if (val == max_val && i < max_idx) {
            max_idx = i;
        }
    }

    output[idx] = max_idx;
}

torch::Tensor argmax_rocm(torch::Tensor input, int dim) {
    auto sizes = input.sizes();
    int64_t reduction_size = sizes[dim];
    int64_t stride_d = input.stride(dim);

    int64_t step_d = 1;
    for (int i=dim+1; i<sizes.size(); i++) {
        step_d *= sizes[i];
    }

    auto output_shape = input.sizes().vec();
    output_shape.erase(output_shape.begin() + dim);
    auto output = torch::empty(output_shape, torch::TensorOptions().dtype(torch::kLong).device(input.device()));

    int64_t output_size = output.numel();
    const int block_size = 256;
    int num_blocks = (output_size + block_size - 1) / block_size;

    hipLaunchKernelGGL(argmax_kernel, 
        num_blocks, block_size, 0, 0, 
        input.data_ptr<float>(), 
        output.data_ptr<int64_t>(), 
        reduction_size, 
        stride_d, 
        step_d, 
        output_size
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* input, const float* weight, const float* bias, float* output,
    int batch_size, int in_channels, int out_channels,
    int input_depth, int input_height, int input_width,
    int output_depth, int output_height, int output_width,
    int kernel_d, int kernel_h, int kernel_w,
    int stride_d, int stride_h, int stride_w,
