    int kh,
    int kw,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w,
    int groups) {

    int n = blockIdx.x;
    int oc = blockIdx.y;
    int spatial = blockIdx.z;
    int oh = spatial / out_w;
    int ow = spatial % out_w;

    if (n >= batch_size || oc >= out_channels || oh >= out_h || ow >= out_w) return;

    int group_in = in_channels / groups;
    int group_out = out_channels / groups;
    int g = oc / group_out;

    float sum = 0.0f;

    for (int ic = 0; ic < group_in; ++ic) {
