            for (int kx = 0; kx < kw; ++kx) {
                int iy = oh * stride_h - pad_h + ky * dilation_h;
                int ix = ow * stride_w - pad_w + kx * dilation_w;

                if (iy >= 0 && iy < in_h && ix >= 0 && ix < in_w) {
                    int inp_idx = n * in_channels * in_h * in_w + (g * group_in + ic) * in_h * in_w + iy * in_w + ix;
