                    sum += input[inp_idx] * weight[wgt_idx];
                }
            }
        }
    }

    if (bias) sum += bias[oc];

    int out_idx = n * out_channels * out_h * out_w + oc * out_h * out_w + oh * out_w + ow;
    output[out_idx] = sum;
