torch::Tensor depthwise_conv2d_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int stride, int padding) {
    const auto batch_size = input.size(0);
    const auto in_channels = input.size(1);
    const auto input_height = input.size(2);
    const auto input_width = input.size(3);
    const auto kernel_size = weight.size(2);
    const auto groups = in_channels;

    const auto output_height = (input_height + 2 * padding - kernel_size) / stride + 1;
    const auto output_width = (input_width + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({batch_size, groups, output_height, output_width}, input.options());
    const int num_elements = output.numel();

    constexpr int block_size = 256;
    const dim3 grid((num_elements + block_size - 1) / block_size);
    const dim3 block(block_size);

    hipStream_t stream = at::hip::getCurrentHIPStream();
    depthwise_conv2d_kernel<<<grid, block, 0, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, groups,
        kernel_size, stride, padding,
        input_height, input_width,
        output_height, output_width
    );

    return output.reshape({batch_size, groups, output_height, output_width});
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void symmetric_matmul_kernel(const float* A, const float* B, float* C, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < N; ++k) {
            sum += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

torch::Tensor symmetric_matmul_rocm(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 threads_per_block(16, 16);
    dim3 num_blocks((N + threads_per_block.x - 1) / threads_per_block.x, (N + threads_per_block.y - 1) / threads_per_block.y);

    symmetric_matmul_kernel<<<num_blocks, threads_per_block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void instance_norm_kernel(const float* input, float* output, int batch_size, int num_features, int height, int width) {
    int idx = (blockIdx.x * blockDim.x + threadIdx.x) * height * width;
    if (idx < batch_size * num_features * height * width) {
        int batch_idx = idx / (num_features * height * width);
        int feature_idx = (idx / (height * width)) % num_features;
        int start_idx = batch_idx * num_features * height * width + feature_idx * height * width;

        float mean = 0.0f;
        float var = 0.0f;

        for (int i = 0; i < height * width; i++) {
            mean += input[start_idx + i];
            var += input[start_idx + i] * input[start_idx + i];
        }

        mean /= (height * width);
        var = var / (height * width) - mean * mean;
        float inv_std = rsqrtf(var + 1e-5);

        for (int i = 0; i < height * width; i++) {
            output[start_idx + i] = (input[start_idx + i] - mean) * inv_std;
        }
    }
}

torch::Tensor instance_norm_rocm(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto num_features = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);
    auto output = torch::empty_like(input);

    dim3 threads(256, 1, 1);
    dim3 blocks((batch_size * num_features + threads.x - 1) / threads.x, 1, 1);

    hipLaunchKernelGGL(instance_norm_kernel, blocks, threads, 0, 0, input.data_ptr<float>(), output.data_ptr<float>(), batch_size, num_features, height, width);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void conv1x1_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int height,
    int width,
    int input_stride_batch,
    int input_stride_channel,
    int input_stride_height,
    int input_stride_width,
    int weight_stride_co,
    int weight_stride_ci
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * out_channels * height * width;
    if (idx >= total) return;

    int elements_per_batch = out_channels * height * width;
    int b = idx / elements_per_batch;
    int tid = idx % elements_per_batch;
    int co = tid / (height * width);
    int spatial_idx = tid % (height * width);
    int h = spatial_idx / width;
    int w = spatial_idx % width;

    float sum = 0.0f;
    for (int ci = 0; ci < in_channels; ++ci) {
        int input_offset = b * input_stride_batch
                         + ci * input_stride_channel
                         + h * input_stride_height
                         + w * input_stride_width;
        int weight_offset = co * weight_stride_co
                          + ci * weight_stride_ci;
        sum += input[input_offset] * weight[weight_offset];
    }

    if (bias != nullptr) {
        sum += bias[co];
    }

    output[idx] = sum;
}

torch::Tensor conv1x1_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    auto input_cont = input.contiguous();
    auto weight_cont = weight.contiguous().view({weight.size(0), weight.size(1)});
    auto bias_cont = bias.defined() ? bias.contiguous() : torch::Tensor();

    auto output = torch::zeros({input_cont.size(0), weight_cont.size(0), input_cont.size(2), input_cont.size(3)}, input_cont.options());

    const float* input_ptr = input_cont.data_ptr<float>();
    const float* weight_ptr = weight_cont.data_ptr<float>();
    const float* bias_ptr = bias_cont.defined() ? bias_cont.data_ptr<float>() : nullptr;
    float* output_ptr = output.data_ptr<float>();

    auto input_strides = input_cont.strides();
    auto weight_strides = weight_cont.strides();

    int total_elements = output.numel();
    int threads = 256;
    int blocks = (total_elements + threads - 1) / threads;

    hipLaunchKernelGGL(conv1x1_kernel,
                    dim3(blocks), dim3(threads), 0, 0,
                    input_ptr,
                    weight_ptr,
                    bias_ptr,
                    output_ptr,
                    input_cont.size(0),
                    input_cont.size(1),
                    weight_cont.size(0),
                    input_cont.size(2),
                    input_cont.size(3),
                    input_strides[0],
                    input_strides[1],
                    input_strides[2],
                    input_strides[3],
                    weight_strides[0],
                    weight_strides[1]);

    return output;
}

#include <torch/extension.h>  
#include <hip/hip_runtime.h>  

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {  
    int row = blockIdx.y * blockDim.y + threadIdx.y;  
    int col = blockIdx.x * blockDim.x + threadIdx.x;  
    if (row < N && col < N) {  
        float sum = 0.0f;  
        for (int k = 0; k < N; ++k) {  
            sum += A[row * N + k] * B[k * N + col];  
        }  
        C[row * N + col] = sum;  
    }  
}  

torch::Tensor matmul_rocm(torch::Tensor A, torch::Tensor B, int N) {  
    auto C = torch::zeros({N, N}, A.options());  
    dim3 threads(16, 16);  
    dim3 blocks((N + threads.x - 1) / threads.x, (N + threads.y - 1) / threads.y);  
    hipLaunchKernelGGL(matmul_kernel, blocks, threads, 0, 0, A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);  
    return C;  
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void triu_matmul_kernel(const float* A, const float* B, float* C, int N) {
    int i = blockIdx.y * blockDim.y + threadIdx.y;
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if (i <= j && i < N && j < N) {
        float sum = 0.0f;
        for (int k = i; k <= j; k++) {
            sum += A[i * N + k] * B[k * N + j];
        }
        C[i * N + j] = sum;
    }
}

torch::Tensor triu_matmul_rocm(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros_like(A);

    dim3 block(16, 16);
    dim3 grid((N + block.x - 1) / block.x, (N + block.y - 1) / block.y);

    hipLaunchKernelGGL(triu_matmul_kernel, grid, block, 0, 0, 
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void conv_transpose1d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels, int kernel_size, 
    int input_length, int output_length, int stride, int padding, 
    int output_padding, int groups, int in_channels_per_group, 
    int out_channels_per_group) {

    int l_out = blockIdx.x * blockDim.x + threadIdx.x;
    int c_out = blockIdx.y * blockDim.y + threadIdx.y;
    int b = blockIdx.z;

    if (b >= batch_size || c_out >= out_channels || l_out >= output_length) return;

    int group = c_out / out_channels_per_group;
    int group_start_in = group * in_channels_per_group;
    float sum = 0.0f;

    for (int c_in_rel = 0; c_in_rel < in_channels_per_group; ++c_in_rel) {
        int c_in = group_start_in + c_in_rel;
        for (int k = 0; k < kernel_size; ++k) {
            int l_in_times_stride = l_out - k + padding;
            if (l_in_times_stride % stride != 0) continue;

            int l_in = l_in_times_stride / stride;
            if (l_in < 0 || l_in >= input_length) continue;

            float input_val = input[b * in_channels * input_length + c_in * input_length + l_in];
            float weight_val = weight[c_in * out_channels_per_group * kernel_size 
                                    + (c_out % out_channels_per_group) * kernel_size + k];
            sum += input_val * weight_val;
        }
    }

    if (bias) sum += bias[c_out];

    output[b * out_channels * output_length + c_out * output_length + l_out] = sum;
}

torch::Tensor conv_transpose1d_rocm(
    torch::Tensor input, torch::Tensor weight, torch::optional<torch::Tensor> bias,
    int stride, int padding, int output_padding, int groups) {

    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto input_length = input.size(2);
    int kernel_size = weight.size(2);
    int out_channels = weight.size(1) * groups;
    int output_length = (input_length - 1)*stride - 2*padding + kernel_size + output_padding;

    auto output = torch::zeros({batch_size, out_channels, output_length}, 
                              input.options());

    int in_channels_per_group = in_channels / groups;
    int out_channels_per_group = out_channels / groups;

    dim3 block(256, 1, 1);
    dim3 grid(
        (output_length + block.x - 1) / block.x,
        out_channels,
        batch_size
    );

    hipLaunchKernelGGL(conv_transpose1d_kernel, grid, block, 0, 0, 
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias ? bias->data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels, kernel_size,
        input_length, output_length, stride, padding, output_padding,
        groups, in_channels_per_group, out_channels_per_group
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size, int in_channels, int out_channels,
    int in_h, int in_w,
    int out_h, int out_w,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    int groups, bool has_bias
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;

    const int total_output = batch_size * out_channels * out_h * out_w;
    if (idx >= total_output) return;

    const int oc = (idx / (out_h * out_w)) % out_channels;
    const int n = idx / (out_channels * out_h * out_w);
    const int oh = (idx / out_w) % out_h;
    const int ow = idx % out_w;

    const int group = oc / (out_channels / groups);
    const int in_ch_per_group = in_channels / groups;

    float sum = 0.0f;

    for (int ic = group * in_ch_per_group; ic < (group + 1) * in_ch_per_group; ++ic) {
        for (int kh = 0; kh < kernel_h; ++kh) {
            for (int kw = 0; kw < kernel_w; ++kw) {
                const int ih = (oh - kh * dilation_h + padding_h) % stride_h;
                const int iw = (ow - kw * dilation_w + padding_w) % stride_w;
                if (ih != 0 || iw != 0) continue;

                const int input_h = (oh - kh * dilation_h + padding_h) / stride_h;
                const int input_w = (ow - kw * dilation_w + padding_w) / stride_w;

                if (input_h < 0 || input_h >= in_h || input_w < 0 || input_w >= in_w) continue;

                const int weight_idx = ic * (out_channels / groups) * kernel_h * kernel_w 
                                    + (oc % (out_channels / groups)) * kernel_h * kernel_w
                                    + kh * kernel_w + kw;

                sum += input[n * in_channels * in_h * in_w + ic * in_h * in_w + input_h * in_w + input_w]
                     * weight[weight_idx];
            }
        }
    }

    if (has_bias) sum += bias[oc];
    output[idx] = sum;
}

torch::Tensor conv_transpose2d_rocm(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    int groups) {

    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto in_h = input.size(2);
    auto in_w = input.size(3);

    auto out_channels = weight.size(1) * groups;
    auto kernel_h = weight.size(2);
    auto kernel_w = weight.size(3);

    auto out_h = (in_h - 1) * stride_h - 2 * padding_h + dilation_h * (kernel_h - 1) + 1;
    auto out_w = (in_w - 1) * stride_w - 2 * padding_w + dilation_w * (kernel_w - 1) + 1;

    auto output = torch::empty({batch_size, out_channels, out_h, out_w}, input.options());

    int num_threads = 256;
    int total_elements = batch_size * out_channels * out_h * out_w;
    int num_blocks = (total_elements + num_threads - 1) / num_threads;

    hipStream_t stream = at::hip::getCurrentHIPStream();
    hipLaunchKernelGGL(
        conv_transpose2d_kernel,
        num_blocks, num_threads, 0, stream,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias ? bias->data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_h, in_w, out_h, out_w,
        kernel_h, kernel_w,
        stride_h, stride_w,
        padding_h, padding_w,
        dilation_h, dilation_w,
        groups, bias.has_value()
    );

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_transpose2d_rocm", &conv_transpose2d_rocm);
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void relu_kernel(const float* x, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = fmaxf(0.0f, x[idx]);
    }
}

torch::Tensor relu_rocm(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
